ext3_fsblk_t get_superblock_block_number(void **data, struct super_block *sb) {
    char *options = (char *)*data;
    ext3_fsblk_t block = 1;  // Default value

    if (!options || strncmp(options, "sb=", 3) != 0) {
        return block;
    }

    // Skip the 'sb=' prefix
    options += 3;

    char *endptr;
    unsigned long parsed_block = simple_strtoul(options, &endptr, 0);

    // Check for invalid characters after the block number
    if (endptr == options || (*endptr != '\0' && *endptr != ',' && *endptr != ':')) {
        printk(KERN_ERR "Invalid characters after superblock block number.");
        return block;
    }

    // Update the data pointer to point to the remaining options
    *data = (void *)endptr;

    // Ensure the parsed block is within a valid range
    if (parsed_block > (unsigned long)~((ext3_fsblk_t)0)) {
        printk(KERN_ERR "Superblock block number is out of valid range.");
        return block;
    }

    block = (ext3_fsblk_t)parsed_block;
    return block;
}
